import subprocess,json,pathlib,tempfile,sys,os
listener="import http.server,json,time,datetime,sys,pathlib,socketserver,threading\nout={'started':datetime.datetime.utcnow().isoformat()+'Z','kind':'isolated QA HA REST simulator, not actual HA hardware','requests':[],'states':{}};lock=threading.Lock();deadline=time.time()+420\nmodes=['normal','fail429','fail500','delay'];entities=['light.qa_q08_ownerfix_'+m for m in modes]\nfor e in entities:out['states'][e]='off'\ndef save():\n with lock:pathlib.Path(sys.argv[2]).write_text(json.dumps(out))\nclass Handler(http.server.BaseHTTPRequestHandler):\n def setup(self):http.server.BaseHTTPRequestHandler.setup(self);self.connection.settimeout(3)\n def log_message(self,*args):pass\n def respond(self,status,body):\n  self.send_response(status);self.send_header('Content-Type','application/json');self.end_headers()\n  try:self.wfile.write(json.dumps(body).encode())\n  except (BrokenPipeError,ConnectionResetError):pass\n def do_GET(self):\n  if self.headers.get('Authorization')!='Bearer qa-q08-isolated-simulation-only':return self.respond(401,{'error':'Unauthorized'})\n  if self.path=='/api/states':return self.respond(200,[{'entity_id':e,'state':out['states'][e],'attributes':{'friendly_name':'QA-Q08-'+e.split('_')[-1]},'last_updated':datetime.datetime.utcnow().isoformat()+'Z'}for e in entities])\n  if self.path.startswith('/api/states/') and self.path[12:] in entities:\n   e=self.path[12:];return self.respond(200,{'entity_id':e,'state':out['states'][e],'attributes':{}})\n  return self.respond(404,{'error':'not found'})\n def do_POST(self):\n  if self.headers.get('Authorization')!='Bearer qa-q08-isolated-simulation-only':return self.respond(401,{'error':'Unauthorized'})\n  try:n=int(self.headers.get('Content-Length','0'));assert 0<=n<=4096;body=json.loads(self.rfile.read(n))\n  except Exception:return self.respond(400,{'error':'invalid body'})\n  e=body.get('entity_id');mode=e.split('_')[-1] if isinstance(e,str) else ''\n  if e not in entities or self.path not in ['/api/services/light/turn_on','/api/services/light/turn_off']:return self.respond(404,{'error':'unknown QA entity/path'})\n  row={'at':datetime.datetime.utcnow().isoformat()+'Z','path':self.path,'entity_id':e,'mode':mode,'executed':False};out['requests'].append(row);save()\n  if mode=='fail429':row['status']=429;save();return self.respond(429,{'error':'QA rate limited'})\n  if mode=='fail500':row['status']=500;save();return self.respond(500,{'error':'QA injected failure'})\n  if mode=='delay':time.sleep(11);row['status']=504;save();return self.respond(504,{'error':'QA delay no execution'})\n  out['states'][e]='on' if self.path.endswith('turn_on') else 'off';row['executed']=True;row['status']=200;save();return self.respond(200,[])\nclass Server(socketserver.ThreadingMixIn,http.server.HTTPServer):daemon_threads=True\nsave()\nwith Server((sys.argv[1],35181),Handler) as s:\n s.timeout=1\n while time.time()<deadline:s.handle_request()\nout['stopped']=True;save()\n"
ids=subprocess.check_output(['docker','ps','-q']).decode().split();gateway=None
for cid in ids:
 x=json.loads(subprocess.check_output(['docker','inspect',cid]))[0]
 for n,v in x['NetworkSettings']['Networks'].items():
  if 'tp-plugin-http-adapter' in (v.get('Aliases') or []) and v.get('Gateway'):gateway=v['Gateway']
if not gateway:raise RuntimeError('HTTP plugin bridge gateway not found; refusing public bind')
d=pathlib.Path(tempfile.mkdtemp(prefix='qa-q08-ha-fault-'));os.chmod(str(d),0o700);p=d/'listener.py';p.write_text(listener);result=d/'result.json';log=(d/'server.log').open('wb')
child=subprocess.Popen([sys.executable,str(p),gateway,str(result)],stdin=subprocess.DEVNULL,stdout=log,stderr=log,start_new_session=True,close_fds=True)
print(json.dumps({'pid':child.pid,'host':gateway,'port':35181,'deadline_seconds':420,'result_path':str(result),'log_path':str(d/'server.log')}))
